class Solution {
public:
    int removePalindromeSub(string s) {
        int n = s.size();
        if (n == 0) return 0;
        int i = 0, j = n - 1;
        bool isPalin = true;
        while (i < j) {
            if (s[i] != s[j]) {
                isPalin = false;
                break;
            }
            i++;
            j--;
        }
        return isPalin ? 1 : 2;
    }
};
